// One reference: a sentence of description, then its source URL as a live link.
const ref=(text,url)=>new Paragraph({spacing:{after:130,line:264},indent:{left:360,hanging:360},children:[
  new TextRun({text:text+"  ",font:FONT,size:20}),
  new ExternalHyperlink({link:url,children:[new TextRun({text:url,font:FONT,size:18,color:NAVY,underline:{}})]}),
]});

