// Section 4: each recommendation renders the same way.
const REC=(n,heading,objective,actions,evidence,owner)=>[
 h2(n+" "+heading),
 p([b("Objective. "),tx(objective)]),
 label("PRIORITY ACTIONS"),
 ...actions.map(a=>bl(a)),
 label("EVIDENCE OF PROGRESS"),
 ...evidence.map(e=>bl(e)),
 p([b("Primary ownership. "),tx(owner)]),
];

